package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.sql.Connection;
import java.sql.Date;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.LocalDate;
import java.util.List;
import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/** The stored claims, kept per sheet. Ids are assigned in the order claims are added. */
@Repository
public class ClaimRepository {

    private static final String COLUMNS = "id, sheet_id, person_id, amount, claim_date, note, status, claim_number, due, opened_by";

    private final JdbcTemplate jdbc;
    private final DataSource dataSource;

    public ClaimRepository(JdbcTemplate jdbc, DataSource dataSource) {
        this.jdbc = jdbc;
        this.dataSource = dataSource;
    }

    /** The sheet's claims, newest first. */
    public List<Claim> list(String sheetId) {
        return jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? ORDER BY id DESC",
                ClaimRepository::map, sheetId);
    }

    public Claim find(String sheetId, long id) {
        List<Claim> found = jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? AND id = ?",
                ClaimRepository::map, sheetId, id);
        return found.isEmpty() ? null : found.get(0);
    }

    public Claim add(String sheetId, long personId, BigDecimal amount, LocalDate date, String note) {
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note) VALUES (?, ?, ?, ?, ?)",
                    new String[] { "id" });
            ps.setString(1, sheetId);
            ps.setLong(2, personId);
            ps.setBigDecimal(3, amount);
            ps.setDate(4, Date.valueOf(date));
            ps.setString(5, note);
            return ps;
        }, keys);
        return new Claim(keys.getKey().longValue(), sheetId, personId, amount, date, note, ClaimStatus.DRAFT, null, null, null);
    }

    public void update(Claim claim) {
        jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, note = ? WHERE sheet_id = ? AND id = ?",
                claim.amount(), Date.valueOf(claim.date()), claim.note(), claim.sheetId(), claim.id());
    }

    /**
     * Stores the claim's status, number, fixed due and who opened it, but only while its status is still {@code from}; false when another
     * change got there first (nothing is written).
     */
    public boolean updateStatus(Claim claim, ClaimStatus from) {
        return jdbc.update("UPDATE claim SET status = ?, claim_number = ?, due = ?, opened_by = ? WHERE sheet_id = ? AND id = ? AND status = ?",
                claim.status().name(), claim.number(), claim.due(), claim.openedBy(), claim.sheetId(), claim.id(), from.name()) == 1;
    }

    /**
     * The sheet's next claim number: 1 for the first, then one more each time. The sheet's counter row stays locked
     * until the transaction ends, so two claims opened at once get different numbers, and a rolled back opening gives
     * its number back.
     */
    public long nextNumber(String sheetId) {
        ensureNumberRow(sheetId);
        jdbc.update("UPDATE claim_number_seq SET last_number = last_number + 1 WHERE sheet_id = ?", sheetId);
        return jdbc.queryForObject("SELECT last_number FROM claim_number_seq WHERE sheet_id = ?", Long.class, sheetId);
    }

    /**
     * Adds the sheet's counter row if it has none, on its own connection so the row is committed at once and two
     * openings at the same moment never both try to add it.
     */
    private synchronized void ensureNumberRow(String sheetId) {
        try (Connection con = dataSource.getConnection()) {
            con.setAutoCommit(true);
            try (PreparedStatement ps = con.prepareStatement("INSERT INTO claim_number_seq (sheet_id, last_number) "
                    + "SELECT ?, 0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM claim_number_seq WHERE sheet_id = ?)")) {
                ps.setString(1, sheetId);
                ps.setString(2, sheetId);
                ps.executeUpdate();
            }
        } catch (SQLException e) {
            throw new IllegalStateException(e);
        }
    }

    private static Claim map(ResultSet rs, int n) throws SQLException {
        BigDecimal due = rs.getBigDecimal("due");
        return new Claim(rs.getLong("id"), rs.getString("sheet_id"), rs.getLong("person_id"),
                rs.getBigDecimal("amount").setScale(2), rs.getObject("claim_date", LocalDate.class),
                rs.getString("note"), ClaimStatus.valueOf(rs.getString("status")),
                rs.getObject("claim_number", Long.class), due == null ? null : due.setScale(2),
                rs.getString("opened_by"));
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * A claim of a person on a sheet: an amount (0.00 or more, two decimals), a date, a note (may be empty), its status
 * its number (given when opened; null for a draft or a voided claim) and its due fixed when settled (null when not
 * settled, or settled while its grade had no rate), and who opened it (null when never opened).
 */
public record Claim(long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
        ClaimStatus status, Long number, BigDecimal due, String openedBy) {
}
package net.officefloor.hq.app.claim;

/** A claim as sent to the screen: the amount as text with two decimals, so it is never rounded through a float;
 *  the number is null when the claim has none; due is the due fixed when settled (two decimals), null while it is
 *  live; openedBy is who opened it, null when never opened. */
public record ClaimResponse(long id, String sheetId, long personId, String amount, String date, String note,
        String status, Long number, String due, String openedBy) {
    public static ClaimResponse from(Claim claim) {
        return new ClaimResponse(claim.id(), claim.sheetId(), claim.personId(), claim.amount().toPlainString(),
                claim.date().toString(), claim.note(), claim.status().name(), claim.number(),
                claim.due() == null ? null : claim.due().toPlainString(), claim.openedBy());
    }
}
package net.officefloor.hq.app.claim;

import java.util.List;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

/** The sheet's claims, newest first. */
public class RespondWithClaims {
    public void respond(@PathVariable("sheetId") String sheetId, ClaimRepository claims,
            ObjectResponse<List<ClaimResponse>> response) {
        response.send(claims.list(sheetId.trim()).stream().map(ClaimResponse::from).toList());
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Moves the claim to its new status: DRAFT to OPEN, OPEN to SETTLED, DRAFT or OPEN to VOID. Voiding clears the
 * claim's number; the number it had is kept for the audit line. Settling fixes the claim's due: its amount at its
 * person's grade's rate in force on the claim's date, rounded half up to two decimals (left live when no rate applies).
 * Opening records who opened the claim; that user cannot settle it (four eyes).
 */
public class ApplyClaimStatus {
    public void apply(@Val Claim claim, @Val ClaimStatusChange change, PersonRepository people, RateRepository rates,
            Out<Claim> changed, Out<ClaimNumber> number) throws InvalidClaimStatusException {
        boolean allowed = switch (change.to()) {
            case OPEN -> claim.status() == ClaimStatus.DRAFT;
            case SETTLED -> claim.status() == ClaimStatus.OPEN;
            case VOID -> claim.status() == ClaimStatus.DRAFT || claim.status() == ClaimStatus.OPEN;
            case DRAFT -> false;
        };
        if (!allowed) {
            throw new InvalidClaimStatusException("A " + claim.status() + " claim cannot be made " + change.to());
        }
        if (change.to() == ClaimStatus.SETTLED && change.by().equals(claim.openedBy())) {
            throw new InvalidClaimStatusException("The user who opened a claim cannot settle it");
        }
        number.set(new ClaimNumber(claim.number()));
        changed.set(new Claim(claim.id(), claim.sheetId(), claim.personId(), claim.amount(), claim.date(),
                claim.note(), change.to(), change.to() == ClaimStatus.VOID ? null : claim.number(),
                change.to() == ClaimStatus.SETTLED ? due(claim, people, rates) : claim.due(),
                change.to() == ClaimStatus.OPEN ? change.by() : claim.openedBy()));
    }

    private static BigDecimal due(Claim claim, PersonRepository people, RateRepository rates) {
        Person person = people.find(claim.sheetId(), claim.personId());
        Rate rate = person == null ? null : rates.find(claim.sheetId(), person.grade(), claim.date());
        return rate == null ? null
                : claim.amount().multiply(rate.rate()).movePointLeft(2).setScale(2, RoundingMode.HALF_EVEN);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Stores the new status. Opening gives the claim the sheet's next number. A change another user made first (the
 * stored status is no longer the one this change started from) is refused, and the transaction gives back the number.
 */
public class SaveClaimStatus {
    public void save(@Val Claim claim, ClaimRepository claims, Out<Claim> saved,
            Out<ClaimNumber> number) throws InvalidClaimStatusException {
        Claim toSave = claim;
        if (claim.status() == ClaimStatus.OPEN) {
            long next = claims.nextNumber(claim.sheetId());
            toSave = new Claim(claim.id(), claim.sheetId(), claim.personId(), claim.amount(), claim.date(),
                    claim.note(), claim.status(), next, claim.due(), claim.openedBy());
            number.set(new ClaimNumber(next));
        }
        ClaimStatus from = switch (claim.status()) {
            case OPEN -> ClaimStatus.DRAFT;
            case SETTLED -> ClaimStatus.OPEN;
            default -> null;
        };
        boolean stored = from != null ? claims.updateStatus(toSave, from)
                : claims.updateStatus(toSave, ClaimStatus.DRAFT) || claims.updateStatus(toSave, ClaimStatus.OPEN);
        if (!stored) {
            throw new InvalidClaimStatusException("The claim was changed by someone else");
        }
        saved.set(toSave);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.variable.Val;

/** Writes CLAIM_OPENED, CLAIM_SETTLED or CLAIM_VOIDED to the audit file once the status is stored, ending
 * with number=<number> when the claim has (or, voided, had) one; CLAIM_SETTLED then ends with the due it fixed
 * (due=n/a when its grade had no rate). */
public class RecordClaimStatusChanged {
    public void record(@Val Claim claim, @Val ClaimStatusChange change, @Val ClaimNumber number,
            PersonRepository people, Audit audit) {
        String event = switch (claim.status()) {
            case OPEN -> "CLAIM_OPENED";
            case SETTLED -> "CLAIM_SETTLED";
            case VOID -> "CLAIM_VOIDED";
            case DRAFT -> "CLAIM_DRAFTED";
        };
        Person person = people.find(claim.sheetId(), claim.personId());
        audit.record(event + " sheet=" + claim.sheetId() + " by=" + change.by() + " person="
                + (person == null ? "" : person.name()) + " amount=" + claim.amount().toPlainString()
                + " date=" + claim.date() + (number.value() == null ? "" : " number=" + number.value())
                + (claim.status() == ClaimStatus.SETTLED
                        ? " due=" + (claim.due() == null ? "n/a" : claim.due().toPlainString()) : ""));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

/** Loads a claim of the sheet by id; one not on the sheet is a 404. */
public class LoadClaim {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("claimId") String claimId,
            ClaimRepository claims, Out<Claim> claim) throws ClaimNotFoundException {
        Claim found;
        try {
            found = claims.find(sheetId.trim(), Long.parseLong(claimId.trim()));
        } catch (NumberFormatException e) {
            found = null;
        }
        if (found == null) {
            throw new ClaimNotFoundException("No claim " + claimId);
        }
        claim.set(found);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandleClaimNotFound {
    public void handle(@Parameter ClaimNotFoundException ex, ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.NOT_FOUND));
    }
}
# PUT /api/sheets/{sheetId}/claims/{claimId}/status — change a claim's status by an action: open
# (DRAFT to OPEN), settle (OPEN to SETTLED) or void (DRAFT or OPEN to VOID). An action the claim's
# status does not allow, settling by the user who opened the claim, or an unknown action, is a 409
# and a claim not on the sheet a 404, neither writing anything. Opening gives the claim the sheet's
# next number and records who opened it; voiding clears the number. Responds with the claim as
# stored.
validate:
  class: net.officefloor.hq.app.claim.ValidateClaimStatus
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyClaimStatus
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaimStatus
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.RecordClaimStatusChanged
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
-- A settled claim's due, fixed when it is settled: its amount at its person's grade's rate at that
-- moment, so later rate changes do not alter it. Null while the claim is not settled, and for a
-- claim settled while its grade had no rate (its due stays live).
ALTER TABLE claim ADD COLUMN due DECIMAL(19, 2);
-- A person's version: 0 when added, one more on each stored edit. An edit names the version it was
-- made from and is refused when the person has been saved since (another user's edit in between).
ALTER TABLE person ADD COLUMN version BIGINT DEFAULT 0 NOT NULL;

